//! Published critical values only. MacKinnon (1996), JAE 11, 601-618:
//! author's urc-1.tab/probs.tab, copyright James G. MacKinnon 1995, preserved
//! in tool/refs/econ; coefficients generated by tool/refs/econ/tests.py.
//! DF F: Dickey-Fuller (1981), Econometrica 49, p.1063, phi1 and phi3.
//! KPSS: Kwiatkowski et al. (1992), J. Econometrics 54, Table 1.
//! See tool/refs/econ/SOURCES.md for provenance and deliberate compatibility
//! limits. Linear probability interpolation, no distribution extrapolation.
use super::*;
fn interpolate(x: f64, xs: &[f64], ys: &[f64]) -> f64 {
    if x <= xs[0] {
        return ys[0];
    }
    for i in 1..xs.len() {
        if x <= xs[i] {
            return ys[i - 1] + (ys[i] - ys[i - 1]) * ((x - xs[i - 1]) / (xs[i] - xs[i - 1]));
        }
    }
    *ys.last().unwrap()
}
#[allow(clippy::too_many_arguments)]
fn result(
    e: &mut Engine,
    n: &str,
    stat: f64,
    alpha: f64,
    probs: &[f64],
    critical: &[f64],
    right: bool,
    out: &mut Execution,
) -> Result<(f64, f64)> {
    let (xs, ys) = if right {
        (
            critical.iter().rev().copied().collect::<Vec<_>>(),
            probs.iter().rev().copied().collect::<Vec<_>>(),
        )
    } else {
        (critical.to_vec(), probs.to_vec())
    };
    if stat < xs[0] || stat > *xs.last().unwrap() {
        let low = if right {
            stat > *xs.last().unwrap()
        } else {
            stat < xs[0]
        };
        warning(
            e,
            n,
            if low {
                "PValueTooSmall"
            } else {
                "PValueTooLarge"
            },
            &format!(
                "Test statistic is outside the published table; p-value is clamped to {}.",
                if low {
                    probs[0]
                } else {
                    *probs.last().unwrap()
                }
            ),
            out,
        )?;
    }
    Ok((
        interpolate(stat, &xs, &ys),
        interpolate(alpha, probs, critical),
    ))
}
#[allow(clippy::too_many_arguments)]
pub(super) fn df(
    e: &mut Engine,
    n: &str,
    model: usize,
    test: &str,
    sample: usize,
    stat: f64,
    alpha: f64,
    out: &mut Execution,
) -> Result<(f64, f64)> {
    if test == "f" {
        return df_f(e, n, model, sample, stat, alpha, out);
    }
    if sample < 20 {
        warning(
            e,
            n,
            "SmallSample",
            "Published MacKinnon response surfaces start at 20 observations; using the T=20 surface.",
            out,
        )?;
    }
    let t = sample.max(20) as f64;
    let b = match (test, model) {
        ("t1", 0) => &T1_AR,
        ("t1", 1) => &T1_ARD,
        ("t1", _) => &T1_TS,
        ("t2", 0) => &T2_AR,
        ("t2", 1) => &T2_ARD,
        _ => &T2_TS,
    };
    let critical = b
        .iter()
        .map(|b| b[0] + b[1] / t + b[2] / t.powi(2) + b[3] / t.powi(3))
        .collect::<Vec<_>>();
    result(e, n, stat, alpha, &PROBS, &critical, false, out)
}
