#[allow(clippy::too_many_arguments)]
fn df_f(
    e: &mut Engine,
    n: &str,
    model: usize,
    sample: usize,
    stat: f64,
    alpha: f64,
    out: &mut Execution,
) -> Result<(f64, f64)> {
    if model == 0 {
        return Err(err(n, "InvalidTest", "Test 'F' is invalid for Model 'AR'."));
    }
    if !(0.01..=0.99).contains(&alpha) {
        return Err(err(
            n,
            "UnsupportedAlpha",
            "Published F tables support Alpha from 0.01 through 0.99 only.",
        ));
    }
    if sample < 25 {
        warning(
            e,
            n,
            "SmallSample",
            "Published Dickey-Fuller F tables start at 25 observations; using the T=25 row.",
            out,
        )?;
    }
    let source = if model == 1 { F_ARD } else { F_TS };
    let inv = [0., 1. / 500., 1. / 250., 1. / 100., 1. / 50., 1. / 25.];
    let critical = (0..8)
        .map(|i| {
            interpolate(
                1. / sample.max(25) as f64,
                &inv,
                &source.iter().rev().map(|r| r[i]).collect::<Vec<_>>(),
            )
        })
        .collect::<Vec<_>>();
    result(e, n, stat, alpha, &F_PROBS, &critical, true, out)
}
pub(super) fn kpss(
    e: &mut Engine,
    trend: bool,
    stat: f64,
    alpha: f64,
    out: &mut Execution,
) -> Result<(f64, f64)> {
    let critical = if trend {
        [0.216, 0.176, 0.146, 0.119]
    } else {
        [0.739, 0.574, 0.463, 0.347]
    };
    result(
        e,
        "kpsstest",
        stat,
        alpha,
        &[0.01, 0.025, 0.05, 0.1],
        &critical,
        true,
        out,
    )
}
